<?php require 'bootstrap.php';require 'layout.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{check_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)throw new RuntimeException('Enter a name, valid email, and password of at least 8 characters.');$s=db()->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);redirect('login.php?registered=1');}catch(Throwable $e){$error='Registration failed. Check your details or use a different email.';}}head_html('Register');?><h1>Create an account</h1><?php if($error):?><p class="alert"><?=e($error)?></p><?php endif;?><form method="post" class="panel stack"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Name<input name="name" required minlength="2"></label><label>Email<input name="email" type="email" required></label><label>Password<input name="password" type="password" required minlength="8"></label><button class="btn">Register</button></form><?php foot_html();